import React, { useRef, useEffect, useState } from "react";
// NOTE: real "peerjs" import removed for this in-chat preview only, since it's
// not part of the sandbox's supported package list. In your own project, put
// back: import Peer from "peerjs";
class Peer {
  constructor() {
    setTimeout(() => {
      this._onError && this._onError({ type: "unsupported-in-preview" });
    }, 300);
  }
  on(evt, cb) {
    if (evt === "error") this._onError = cb;
  }
  connect() { return { on: () => {}, open: false, send: () => {} }; }
  destroy() {}
}

// ---------- BOARD GEOMETRY & CONSTANTS ----------
const SIZE = 680;
const FRAME = 46;
const PMIN = FRAME;
const PMAX = SIZE - FRAME;
const CENTER = SIZE / 2;

const COIN_R = 14.5;
const QUEEN_R = 14.5;
const STRIKER_R = 18.5;
const COIN_MASS = 1;
const STRIKER_MASS = 1.4;
const POCKET_R = 27;
// BUGFIX: this used to be one flat number (23) applied to every object
// regardless of size, so the striker (r=18.5) and a coin (r=14.5) were held
// to the exact same "how close to the pocket's center counts as potted"
// rule. That made potting feel inconsistent -- coins would visibly be
// mostly over the hole and still bounce off, or the threshold would be
// wrong for whichever radius wasn't "typical". pocketCatchRadius() below
// scales the catch distance to the object's own radius so anything whose
// body is mostly over the hole actually drops, matching what it looks like
// on screen.
function pocketCatchRadius(r) {
  return POCKET_R - r * 0.2;
}
const POCKET_MAGNET_R = POCKET_R + 10;

// PHYSICS & FRICTION
// The striker should keep gliding smoothly like before (that's the feel of
// a real striker sliding on the powdered board). Coins, on the other hand,
// were gliding for just as long, which read as "too smooth" / air-hockey-like
// for pieces that are supposed to skid and settle. So the striker keeps the
// original high, smooth friction value, while coins/queen get a lower one
// that bleeds off speed noticeably faster.
const STRIKER_FRICTION = 0.988;
const COIN_FRICTION = 0.965;
const MIN_SPEED = 0.08;
const MAX_PULL = 120;
const POWER_SCALE = 0.18;
const ARROW_LENGTH_MULT = 2.6;
const WALL_REST = 0.82;
const COLL_REST = 0.98;

const BASE_OFFSET = 44;
const EDGE_MARGIN = 72;
// Radius of the little red "stand" circle drawn at each end of a baseline
// (see drawBaseline). BUGFIX: this used to be declared *inside* drawBaseline
// only, so nothing constraining striker movement knew about it -- the
// striker's slide range was clamped to EDGE_MARGIN alone, which is 12px
// short of where the red circle actually sits (EDGE_MARGIN + END_CIRCLE_R).
// That let the striker slide past the visual stand marker, out toward the
// pocket/frame corner. STRIKER_STAND_MARGIN below is the corrected, shared
// bound: it's what every clamp should use so the striker never travels
// further than the red circle itself.
const END_CIRCLE_R = 12;
const STRIKER_STAND_MARGIN = EDGE_MARGIN + END_CIRCLE_R;

// PeerJS room codes get this prefix so they don't collide with other apps'
// peers on the shared public PeerJS cloud broker.
const ROOM_PREFIX = "tournament-carrom-";

// ---------- BOT DIFFICULTY TUNING ----------
// BOT_SKILL is a 0..1 dial for how "good" the bot is. It does NOT directly
// set a win percentage (that depends on physics + luck), but it's tuned so
// that over many matches the bot wins roughly 50% of games and the human
// player wins roughly 50% — an even match. Raise it toward 1 for a tougher
// bot, lower it toward 0 for an easier one.
//
// Calibrated by headless simulation of the real physics (bot vs a typical
// player model): BOT_SKILL=0.9 measures ~49% bot / ~51% human over hundreds
// of full matches.
const BOT_SKILL = 0.9;
// Max angle error (radians) the bot's aim can miss by, scaled by (1 - skill).
const BOT_MAX_AIM_ERROR = 0.5;
// Chance the bot completely fumbles its target choice and just goes for
// *some* active coin instead of a smart one, scaled by (1 - skill).
const BOT_MISCUE_CHANCE = 0.28;

const POCKETS = [
  { x: PMIN + 8, y: PMIN + 8 },
  { x: PMAX - 8, y: PMIN + 8 },
  { x: PMIN + 8, y: PMAX - 8 },
  { x: PMAX - 8, y: PMAX - 8 },
];

// Real recorded "bumper shot" collision sample (base64, embedded so the
// artifact is self-contained) used for striker/coin impacts, replacing the
// old synthesized collision blip.
const COLLISION_SOUND_B64 = "";

function base64ToArrayBuffer(base64) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

function triggerHaptic(pattern) {
  if (typeof window !== "undefined" && "vibrate" in navigator) {
    try {
      navigator.vibrate(pattern);
    } catch (e) {}
  }
}

function makeInitialCoins() {
  const coins = [];
  let id = 0;
  coins.push({ id: id++, x: CENTER, y: CENTER, r: QUEEN_R, color: "queen", active: true, vx: 0, vy: 0, mass: COIN_MASS });
  const ring1 = 31;
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2 + Math.PI / 6;
    coins.push({
      id: id++,
      x: CENTER + Math.cos(a) * ring1,
      y: CENTER + Math.sin(a) * ring1,
      r: COIN_R,
      color: i % 2 === 0 ? "white" : "black",
      active: true, vx: 0, vy: 0, mass: COIN_MASS,
    });
  }
  const ring2 = 58;
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    coins.push({
      id: id++,
      x: CENTER + Math.cos(a) * ring2,
      y: CENTER + Math.sin(a) * ring2,
      r: COIN_R,
      color: i % 2 === 0 ? "black" : "white",
      active: true, vx: 0, vy: 0, mass: COIN_MASS,
    });
  }
  return coins;
}

// Canonical baseline assignment used for BOTH offline and online modes:
// Player 1 is always "bottom" and Player 2 is always "top" in game-space.
// For online play, Player 2's device rotates the canvas 180deg when rendering
// (see draw()), so that their canonical "top" baseline visually lands at the
// BOTTOM of their own phone screen too -- both players see their own striker
// at the bottom of their own device.
function sideForPlayer(player, numPlayers) {
  switch (player) {
    case 1: return "bottom";
    case 2: return "top";
    case 3: return "left";
    case 4: return "right";
    default: return "bottom";
  }
}

function makeStriker(player, numPlayers) {
  const side = sideForPlayer(player, numPlayers);
  const base = { r: STRIKER_R, vx: 0, vy: 0, active: true, side, mass: STRIKER_MASS };

  if (side === "bottom") return { ...base, x: CENTER, y: PMAX - BASE_OFFSET };
  if (side === "top") return { ...base, x: CENTER, y: PMIN + BASE_OFFSET };
  if (side === "left") return { ...base, x: PMIN + BASE_OFFSET, y: CENTER };
  return { ...base, x: PMAX - BASE_OFFSET, y: CENTER };
}

// Fallback, fixed odd/even color assignment -- only used for the (currently
// unreachable via the UI) 3-4 player mode where the dynamic white/black
// "first coin decides" rule below doesn't cleanly apply.
function defaultColorForPlayer(player) {
  return player % 2 === 1 ? "white" : "black";
}

function otherColor(color) {
  return color === "white" ? "black" : "white";
}

// Real carrom rule: nobody is "white" or "black" at the start. Colors are
// undecided (null) until a player pockets their first non-queen coin --
// whichever color they potted becomes theirs for the rest of the game, and
// their opponent is automatically the other color. Falls back to fixed
// odd/even assignment for >2 players.
function getPlayerColor(st, player) {
  if (st.numPlayers === 2) {
    return (st.playerColors && st.playerColors[player]) || null;
  }
  return defaultColorForPlayer(player);
}

function initialScores(numPlayers) {
  const s = {};
  for (let p = 1; p <= numPlayers; p++) {
    s[p] = 9;
  }
  return s;
}

function resolveStrikerAxis(desired, fixed, coins, axis) {
  let val = desired;
  for (const c of coins) {
    if (!c.active) continue;
    const other = axis === "x" ? fixed - c.y : fixed - c.x;
    const minDist = STRIKER_R + c.r;
    if (Math.abs(other) >= minDist) continue;
    const allowed = Math.sqrt(minDist * minDist - other * other);
    const center = axis === "x" ? c.x : c.y;
    const lo = center - allowed;
    const hi = center + allowed;
    if (val > lo && val < hi) {
      val = val - center < 0 ? lo : hi;
    }
  }
  return val;
}

